function collides(x,y,r=14){if(x<35||y<35||x>W-35||y>H-35)return true;for(const b of buildings)if(x+r>b.x&&x-r<b.x+b.w&&y+r>b.y&&y-r<b.y+b.h)return true;return false}
function addBurst(x,y,color,n=8,power=120){for(let i=0;i<n;i++){let a=rnd()*Math.PI*2,s=30+rnd()*power;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.35+rnd()*.55,color,size:2+rnd()*4})}}
function drive(c,dt){let t=types[c.type],forward=c.vx*Math.cos(c.a)+c.vy*Math.sin(c.a),acc=(keys.w||keys.ArrowUp?1:0)-(keys.s||keys.ArrowDown?1:0);let steer=(keys.a||keys.ArrowLeft?1:0)-(keys.d||keys.ArrowRight?1:0);let hand=keys[' '];c.vx+=Math.cos(c.a)*acc*t.accel*dt;c.vy+=Math.sin(c.a)*acc*t.accel*dt;c.a+=steer*t.turn*dt*(.3+Math.min(1,Math.abs(forward)/90))*(forward<0?-1:1);let side=-c.vx*Math.sin(c.a)+c.vy*Math.cos(c.a),grip=hand?1.35:5.7;c.vx-=Math.sin(c.a)*side*Math.min(1,grip*dt);c.vy+=Math.cos(c.a)*side*Math.min(1,grip*dt);let drag=Math.pow(acc?0.994:0.982,dt*60);c.vx*=drag;c.vy*=drag;let max=t.speed*(1-c.damageRatio*.48);let speed=Math.hypot(c.vx,c.vy);if(speed>max){c.vx*=max/speed;c.vy*=max/speed}let nx=c.x+c.vx*dt,ny=c.y+c.vy*dt;if(collides(nx,ny,23)){if(Math.abs(forward)>90){c.hp-=Math.abs(forward)*.018;addBurst(c.x,c.y,'#ffb34e',4,60);if(c===player.car){player.hp-=Math.max(1,Math.abs(forward)*.006);if(c.hp<=0){player.car=null;player.hp=Math.max(15,player.hp-15);toast('Vehicle wrecked!')}}}c.vx*=-.28;c.vy*=-.28}else{c.x=nx;c.y=ny}c.damageRatio=1-c.hp/c.maxHp;if(c.ai==='player'){player.x=c.x;player.y=c.y;player.angle=c.a;player.vx=c.vx;player.vy=c.vy}if(hand&&speed>110&&rnd()<dt*12)addBurst(c.x-Math.cos(c.a)*16,c.y-Math.sin(c.a)*16,'#c7c9cd',1,20)}
function spawnPolice(){let a=rnd()*Math.PI*2,d=500+rnd()*250,x=clamp(player.x+Math.cos(a)*d,80,W-80),y=clamp(player.y+Math.sin(a)*d,80,H-80);if(collides(x,y,30)){x=ROAD0+Math.round((player.x-ROAD0)/STEP)*STEP+48;y=ROAD0+Math.round((player.y-ROAD0)/STEP)*STEP-48}addCar(x,y,2,a,true);let c=cars[cars.length-1];c.ai='chase';c.hp=types[2].hp;toast('警察 pursuit unit inbound!')}
